create extension if not exists pgcrypto;
create type item_status as enum ('to_buy','owned','reserved','ordered','purchased','unavailable','review');
create table profiles (id uuid primary key references auth.users on delete cascade, locale text not null default 'fr-CA', currency char(3) not null default 'CAD', tax_rate numeric(6,5) not null default 0.14975, created_at timestamptz not null default now());
create table school_levels (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, name text not null, sort_order int not null default 0, unique(user_id,name));
create table school_lists (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, level_id uuid not null references school_levels on delete cascade, title text not null, source_file_path text, import_status text not null default 'validated', created_at timestamptz not null default now());
create table catalog_items (id uuid primary key default gen_random_uuid(), canonical_name text not null, category text, default_unit text not null default 'unité');
create table school_list_items (id uuid primary key default gen_random_uuid(), list_id uuid not null references school_lists on delete cascade, catalog_item_id uuid references catalog_items, quantity numeric(10,2) not null check(quantity>0), color text, format text, dimensions text, mandatory_attributes jsonb not null default '{}', preferred_attributes jsonb not null default '{}', comments text, mandatory_merchant_id uuid, status item_status not null default 'to_buy');
create table inventory_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, catalog_item_id uuid references catalog_items, name text not null, quantity numeric(10,2) not null check(quantity>=0), color text, format text, attributes jsonb not null default '{}', note text, updated_at timestamptz not null default now());
create table merchants (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, provider_type text not null default 'manual', active boolean not null default true);
alter table school_list_items add constraint school_list_items_merchant_fk foreign key(mandatory_merchant_id) references merchants(id);
create table merchant_locations (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references merchants on delete cascade, user_id uuid references profiles on delete cascade, name text not null, address text, province char(2) default 'QC', favorite boolean not null default false);
create table products (id uuid primary key default gen_random_uuid(), merchant_id uuid not null references merchants on delete cascade, external_id text, name text not null, url text, package_quantity numeric(10,2) not null default 1, package_unit text not null default 'unité', attributes jsonb not null default '{}', unique(merchant_id,external_id));
create table product_matches (id uuid primary key default gen_random_uuid(), school_list_item_id uuid not null references school_list_items on delete cascade, product_id uuid not null references products on delete cascade, compatibility text not null check(compatibility in ('exact','review','rejected')), differences jsonb not null default '[]', confirmed boolean not null default false, unique(school_list_item_id,product_id));
create table prices (id uuid primary key default gen_random_uuid(), product_id uuid not null references products on delete cascade, location_id uuid references merchant_locations on delete cascade, regular_price numeric(10,2) not null, sale_price numeric(10,2), currency char(3) not null default 'CAD', available boolean not null default true, source text not null default 'manual', checked_at timestamptz not null default now());
create table promotions (id uuid primary key default gen_random_uuid(), user_id uuid references profiles on delete cascade, merchant_id uuid not null references merchants on delete cascade, name text not null, promotion_type text not null, value numeric(10,2) not null, threshold numeric(10,2), conditions jsonb not null default '{}', starts_at timestamptz, ends_at timestamptz, active boolean not null default true);
create table coupons (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, merchant_id uuid not null references merchants on delete cascade, name text not null, discount_type text not null default 'fixed', value numeric(10,2) not null, expires_at date, active boolean not null default true);
create table shopping_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, strategy text not null, avoid_store_cost numeric(10,2) not null default 10, estimated_subtotal numeric(10,2) not null, discount_total numeric(10,2) not null default 0, estimated_tax numeric(10,2) not null default 0, status text not null default 'active', created_at timestamptz not null default now());
create table shopping_plan_items (id uuid primary key default gen_random_uuid(), plan_id uuid not null references shopping_plans on delete cascade, school_list_item_id uuid not null references school_list_items, merchant_id uuid not null references merchants, product_id uuid references products, quantity_needed numeric(10,2) not null, packages_to_buy int not null, estimated_cost numeric(10,2) not null, checked boolean not null default false);
create table purchases (id uuid primary key default gen_random_uuid(), user_id uuid not null references profiles on delete cascade, plan_item_id uuid references shopping_plan_items, merchant_id uuid not null references merchants, purchased_at timestamptz not null default now(), actual_price numeric(10,2) not null, quantity_purchased numeric(10,2) not null, surplus_to_inventory numeric(10,2) not null default 0);
create index on school_lists(user_id); create index on inventory_items(user_id); create index on prices(product_id,checked_at desc); create index on shopping_plans(user_id,created_at desc);
alter table profiles enable row level security; alter table school_levels enable row level security; alter table school_lists enable row level security; alter table inventory_items enable row level security; alter table coupons enable row level security; alter table shopping_plans enable row level security; alter table purchases enable row level security;
create policy "own profile" on profiles using(id=auth.uid()) with check(id=auth.uid()); create policy "own levels" on school_levels using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own lists" on school_lists using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own inventory" on inventory_items using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own coupons" on coupons using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own plans" on shopping_plans using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "own purchases" on purchases using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into merchants(slug,name,provider_type) values ('jean-coutu','Jean Coutu','manual'),('bureau-en-gros','Bureau en Gros','manual'),('commande-scolaire','Commande Scolaire','manual') on conflict do nothing;
